'use strict';
// Sites & traffic: which sites each subscriber looks up (DNS) and a Torch-style view of the busiest live connections.
const sitesView={range:1,routerId:'',client:'',q:'',tab:'sites',request:0,data:null};
const bytesText=n=>{if(!Number.isFinite(n))return '—';const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++;}return (n>=10||i===0?Math.round(n):n.toFixed(1))+' '+u[i];};
const rateText=n=>Number.isFinite(n)?(n>=1e6?(n/1e6).toFixed(n>=1e7?0:1)+' Mbps':n>=1e3?Math.round(n/1e3)+' kbps':Math.round(n)+' bps'):'—';
const who=item=>`<strong>${h(item.name)}</strong><small>${h(item.ip||item.local||item.client||'')}${item.source?' · '+h(item.source.toUpperCase()):''}${item.routerName?' · '+h(item.routerName):''}</small>`;
function sitesBar(value,max){const pct=max?Math.max(2,Math.round(value/max*100)):0;return `<span class="sites-bar"><i style="width:${pct}%"></i></span>`;}
function sitesCsv(name,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function paintSites(d){
 sitesView.data=d;
 $('#sites-metrics').innerHTML=[['Lookups',d.lookups.toLocaleString(),'DNS queries in this period'],['Unique sites',d.uniqueSites.toLocaleString(),'Different domains visited'],['Active subscribers',d.activeClients.toLocaleString(),'Addresses that looked up sites'],['Live connections',d.liveConnections.toLocaleString(),'Busiest flows right now (over 1 MB)']].map(([t,v,p])=>`<div class="card metric-card"><div><div class="metric-title">${t}</div><div class="metric-value">${v}</div><p>${p}</p></div></div>`).join('');
 const clientOptions='<option value="">All subscribers</option>'+d.topClients.map(c=>`<option value="${h(c.id)}" ${sitesView.client===c.id?'selected':''}>${h(c.name)} (${h(c.ip)})</option>`).join('');
 $('#sites-client').innerHTML=clientOptions;
 $('#sites-router').innerHTML='<option value="">All MikroTiks</option>'+d.routers.map(r=>`<option value="${r.id}" ${sitesView.routerId===r.id?'selected':''}>${h(r.name)}</option>`).join('');
 const maxSite=d.topSites[0]?.lookups||0;
 $('#sites-top').innerHTML=table(['#','SITE','LOOKUPS','','SUBSCRIBERS'],d.topSites.slice(0,500),(s,i)=>`<tr><td class="muted">${i+1}</td><td><strong>${h(s.domain)}</strong></td><td>${s.lookups.toLocaleString()}</td><td class="sites-bar-cell">${sitesBar(s.lookups,maxSite)}</td><td>${s.clients}</td></tr>`,'No DNS lookups have been reported yet. Turn on DNS logging (setup below) and reinstall the discovery script.');
 $('#sites-clients').innerHTML=d.topClients.length?d.topClients.slice(0,300).map(c=>`<details class="card sites-client"><summary><span>${who(c)}</span><span class="sites-client-stats"><b>${c.lookups.toLocaleString()}</b> lookups · <b>${c.uniqueSites}</b> sites</span></summary>${table(['SITE','LOOKUPS',''],c.sites.slice(0,200),s=>`<tr><td>${h(s.domain)}</td><td>${s.lookups.toLocaleString()}</td><td class="sites-bar-cell">${sitesBar(s.lookups,c.sites[0].lookups)}</td></tr>`)}</details>`).join(''):'<div class="list-empty">No subscriber lookups in this period.</div>';
 $('#sites-live').innerHTML=table(['SUBSCRIBER','REMOTE ADDRESS','PROTOCOL','TRANSFERRED','UPLOAD','DOWNLOAD','ROUTER'],d.live.slice(0,400),r=>`<tr><td>${who({name:r.name,local:r.local})}</td><td><strong>${h(r.remote)}</strong>${r.port?'<small>port '+r.port+'</small>':''}<small><a href="https://ipinfo.io/${encodeURIComponent(r.remote)}" target="_blank" rel="noopener noreferrer">Who owns this address?</a></small></td><td>${h((r.proto||'').toUpperCase())}</td><td>${bytesText(r.bytes)}</td><td>${rateText(r.upBps)}</td><td>${rateText(r.downBps)}</td><td>${h(r.routerName)}<small>${h(stamp(r.observedAt))}</small></td></tr>`,'No live connections reported in the last 10 minutes.');
 $('#sites-recent').innerHTML=table(['TIME','SUBSCRIBER','SITE','TYPE','ROUTER TIME'],d.recent.slice(0,500),q=>`<tr><td>${h(stamp(q.at))}</td><td>${who({name:q.name,ip:q.client})}</td><td><strong>${h(q.domain)}</strong></td><td>${h(q.type)}</td><td class="muted">${h(q.routerTime||'')}</td></tr>`,'No lookups yet.');
 $('#sites-setup-commands').textContent=d.setup.join('\n');
 for(const b of document.querySelectorAll('[data-sites-tab]'))b.classList.toggle('active',b.dataset.sitesTab===sitesView.tab);
 for(const p of document.querySelectorAll('[data-sites-panel]'))p.hidden=p.dataset.sitesPanel!==sitesView.tab;
}
async function loadSites(){const request=++sitesView.request;const params=new URLSearchParams({range:sitesView.range,routerId:sitesView.routerId,client:sitesView.client,q:sitesView.q});try{const d=await api('sites?'+params);if(request!==sitesView.request||state.page!=='sites')return;paintSites(d);}catch(error){if(request===sitesView.request)$('#sites-content').innerHTML=notice('Could not load Sites & traffic',h(error.message),true);}}
function renderSites(){
 $('#main').innerHTML=heading('Sites & traffic','Which sites each subscriber visits (from DNS lookups) and the busiest live connections, like MikroTik Torch.','<button class="button secondary" id="sites-export">Export CSV</button><button class="button secondary" id="sites-refresh">Refresh</button>')+
 `<div id="sites-content"><div class="table-toolbar sites-toolbar"><div class="segmented" role="group" aria-label="Period">${[[1,'Today'],[7,'7 days'],[30,'30 days']].map(([v,l])=>`<button type="button" data-sites-range="${v}" class="${sitesView.range===v?'active':''}">${l}</button>`).join('')}</div><input type="search" id="sites-query" placeholder="Search site, subscriber, IP or MAC" aria-label="Search sites" value="${h(sitesView.q)}"><select id="sites-client" aria-label="Subscriber"></select><select id="sites-router" aria-label="MikroTik"></select></div>
 <div id="sites-metrics" class="dashboard-cards sites-cards"><div class="card metric-card"><p>Loading…</p></div></div>
 <div class="sites-tabs" role="tablist">${[['sites','Top sites'],['subscribers','By subscriber'],['live','Live traffic (Torch)'],['recent','Lookup log'],['setup','Setup']].map(([k,l])=>`<button type="button" role="tab" data-sites-tab="${k}">${l}</button>`).join('')}</div>
 <section class="card sites-panel" data-sites-panel="sites"><div class="card-header"><div><h2>Top sites</h2><p>Most looked-up domains across the selected subscribers and period.</p></div></div><div id="sites-top"></div></section>
 <section class="sites-panel" data-sites-panel="subscribers" hidden><div id="sites-clients" class="sites-clients"></div></section>
 <section class="card sites-panel" data-sites-panel="live" hidden><div class="card-header"><div><h2>Live traffic</h2><p>Busiest connections from the latest router report (every 2 minutes), largest first. Encrypted sites show as IP addresses.</p></div></div><div id="sites-live"></div></section>
 <section class="card sites-panel" data-sites-panel="recent" hidden><div class="card-header"><div><h2>Lookup log</h2><p>Every DNS lookup received, newest first (last 1,000 per MikroTik).</p></div></div><div id="sites-recent"></div></section>
 <section class="card sites-panel" data-sites-panel="setup" hidden><div class="card-header"><div><h2>Turn on site monitoring</h2><p>Run once on each MikroTik (WinBox → New Terminal), then reinstall its discovery script from Customer discovery so it starts reporting sites and live connections. These commands change router logging and DNS settings; nothing is sent automatically.</p></div></div><pre class="sites-setup" id="sites-setup-commands"></pre><p class="muted sites-note">Subscribers must use the MikroTik as their DNS server (the PPPoE profile's DNS). Devices set to other DNS servers or encrypted DNS (DNS-over-HTTPS) do not appear in the lookup data, but their connections still appear under Live traffic.</p></section></div>`;
 $('#sites-refresh').onclick=loadSites;
 $('#sites-export').onclick=()=>{const d=sitesView.data;if(!d)return;if(sitesView.tab==='live')sitesCsv('live-traffic.csv',[['subscriber','local','remote','port','protocol','bytes','upload_bps','download_bps','router'],...d.live.map(r=>[r.name,r.local,r.remote,r.port,r.proto,r.bytes,r.upBps,r.downBps,r.routerName])]);else if(sitesView.tab==='recent')sitesCsv('lookups.csv',[['time','subscriber','ip','site','type','router'],...d.recent.map(q=>[new Date(q.at).toISOString(),q.name,q.client,q.domain,q.type,q.routerName])]);else if(sitesView.tab==='subscribers')sitesCsv('sites-by-subscriber.csv',[['subscriber','ip','mac','router','site','lookups'],...d.topClients.flatMap(c=>c.sites.map(s=>[c.name,c.ip,c.mac,c.routerName,s.domain,s.lookups]))]);else sitesCsv('top-sites.csv',[['site','lookups','subscribers'],...d.topSites.map(s=>[s.domain,s.lookups,s.clients])]);};
 for(const b of document.querySelectorAll('[data-sites-range]'))b.onclick=()=>{sitesView.range=Number(b.dataset.sitesRange);for(const x of document.querySelectorAll('[data-sites-range]'))x.classList.toggle('active',x===b);loadSites();};
 for(const b of document.querySelectorAll('[data-sites-tab]'))b.onclick=()=>{sitesView.tab=b.dataset.sitesTab;if(sitesView.data)paintSites(sitesView.data);};
 let debounce;$('#sites-query').oninput=e=>{sitesView.q=e.target.value;clearTimeout(debounce);debounce=setTimeout(loadSites,250);};
 $('#sites-client').onchange=e=>{sitesView.client=e.target.value;loadSites();};$('#sites-router').onchange=e=>{sitesView.routerId=e.target.value;loadSites();};
 loadSites();
}
setInterval(()=>{if(state.session?.user&&state.page==='sites'&&!document.hidden&&!$('dialog[open]'))loadSites();},60000);
// Dashboard panels: today's top sites and the busiest live connections, always shown with links to the full page.
async function loadDashboardSites(){const box=$('#dashboard-sites');if(!box)return;let d;try{d=await api('sites?range=1');}catch{return;}if(!$('#dashboard-sites')||state.page!=='dashboard')return;
 const max=d.topSites[0]?.lookups||0;
 box.innerHTML=`<section class="card"><div class="card-header"><h2>Top sites today</h2><a class="button ghost" href="#sites">View all →</a></div>${table(['SITE','LOOKUPS','','SUBSCRIBERS'],d.topSites.slice(0,8),s=>`<tr><td><strong>${h(s.domain)}</strong></td><td>${s.lookups.toLocaleString()}</td><td class="sites-bar-cell">${sitesBar(s.lookups,max)}</td><td>${s.clients}</td></tr>`,'No DNS lookups reported yet. Open Sites & traffic → Setup.')}</section><section class="card"><div class="card-header"><h2>Live traffic now</h2><a class="button ghost" href="#sites" data-sites-open="live">View all →</a></div>${table(['SUBSCRIBER','REMOTE','TRANSFERRED','DOWN'],d.live.slice(0,8),r=>`<tr><td>${who({name:r.name,local:r.local})}</td><td><strong>${h(r.remote)}</strong>${r.port?'<small>port '+r.port+'</small>':''}</td><td>${bytesText(r.bytes)}</td><td>${rateText(r.downBps)}</td></tr>`,'No live connections in the last 10 minutes.')}</section>`;
 box.querySelector('[data-sites-open]').onclick=()=>{sitesView.tab='live';};}
setInterval(()=>{if(state.session?.user&&state.page==='dashboard'&&!document.hidden&&!$('dialog[open]'))loadDashboardSites();},60000);
